import{_ as n,o as e,c as s,a0 as i}from"./chunks/framework.DoRPXVp_.js";const u=JSON.parse('{"title":"ICE Connection & LRP Relay","description":"","frontmatter":{"title":"ICE Connection & LRP Relay"},"headers":[],"relativePath":"design/ice-connection.md","filePath":"design/ice-connection.md"}'),t={name:"design/ice-connection.md"};function l(r,a,p,o,c,d){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="ice-connection-lrp-relay" tabindex="-1">ICE Connection &amp; LRP Relay <a class="header-anchor" href="#ice-connection-lrp-relay" aria-label="Permalink to &quot;ICE Connection &amp; LRP Relay&quot;">​</a></h1><blockquote><p>Source: <code>superpowers/specs/2026-05-01-ice-relay-wireguard-design.md</code></p></blockquote><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Lattice connects nodes across arbitrary network topologies — home LANs, corporate firewalls, cloud VPCs. A WireGuard mesh alone fails behind symmetric NAT. The transport layer addresses this with a <strong>dual-path strategy</strong>: direct P2P via ICE when possible, relay fallback via LRP when NAT traversal fails.</p><p>Design priorities:</p><ol><li><strong>Lowest latency wins</strong>: ICE direct path preferred; LRP is the fallback</li><li><strong>Seamless upgrade</strong>: LRP → ICE upgrade happens transparently mid-connection</li><li><strong>Single port</strong>: WireGuard and ICE share UDP port 51820 via a filtering mux</li><li><strong>Multi-transport relay</strong>: LRP supports both TCP (HTTP upgrade) and QUIC (datagram)</li></ol><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          Peer A                                  Peer B</span></span>
<span class="line"><span>      ┌───────────┐                          ┌───────────┐</span></span>
<span class="line"><span>      │   wf0     │                          │   wf0     │</span></span>
<span class="line"><span>      │   TUN     │                          │   TUN     │</span></span>
<span class="line"><span>      └─────┬─────┘                          └─────┬─────┘</span></span>
<span class="line"><span>            │                                      │</span></span>
<span class="line"><span>      ┌─────▼─────┐                          ┌─────▼─────┐</span></span>
<span class="line"><span>      │ WireGuard │                          │ WireGuard │</span></span>
<span class="line"><span>      │  Device   │                          │  Device   │</span></span>
<span class="line"><span>      └─────┬─────┘                          └─────┬─────┘</span></span>
<span class="line"><span>            │                                      │</span></span>
<span class="line"><span>  ┌─────────▼─────────┐                  ┌─────────▼─────────┐</span></span>
<span class="line"><span>  │   FilteringUDPMux  │                  │   FilteringUDPMux  │</span></span>
<span class="line"><span>  │   :51820           │                  │   :51820           │</span></span>
<span class="line"><span>  └──┬─────────────┬──┘                  └──┬─────────────┬──┘</span></span>
<span class="line"><span>     │             │                        │             │</span></span>
<span class="line"><span>┌────▼────┐  ┌─────▼──────┐          ┌────▼────┐  ┌─────▼──────┐</span></span>
<span class="line"><span>│ ICE     │  │ LRP Client │          │ ICE     │  │ LRP Client │</span></span>
<span class="line"><span>│ Agent   │  │ (TCP/QUIC) │          │ Agent   │  │ (TCP/QUIC) │</span></span>
<span class="line"><span>└─────────┘  └─────┬──────┘          └─────────┘  └─────┬──────┘</span></span>
<span class="line"><span>                   └──────── Relay Server ────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>     Signaling: NATS (lattice.signals.peers.&lt;PeerID&gt;)</span></span></code></pre></div><h2 id="ice-nat-traversal" tabindex="-1">ICE / NAT Traversal <a class="header-anchor" href="#ice-nat-traversal" aria-label="Permalink to &quot;ICE / NAT Traversal&quot;">​</a></h2><p>Built on <a href="https://github.com/pion/ice" target="_blank" rel="noreferrer">pion/ice v4</a>.</p><ul><li>STUN servers for reflexive address discovery</li><li>TURN servers for relay candidates (fallback within ICE)</li><li><code>FilteringUDPMux</code> demultiplexes STUN and WireGuard packets on the same port</li></ul><h2 id="lrp-relay" tabindex="-1">LRP Relay <a class="header-anchor" href="#lrp-relay" aria-label="Permalink to &quot;LRP Relay&quot;">​</a></h2><p>LRP (Lattice Relay Protocol) is the outer relay when ICE fails (e.g., symmetric NAT on both sides):</p><ul><li>TCP transport: HTTP-upgraded persistent connection</li><li>QUIC transport: datagram-based, eliminates head-of-line blocking</li></ul><h2 id="connection-state-machine" tabindex="-1">Connection State Machine <a class="header-anchor" href="#connection-state-machine" aria-label="Permalink to &quot;Connection State Machine&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Created → Probing → ICEReady / LRPReady → Failed → Closed</span></span></code></pre></div><p>ICE and LRP probe in parallel. First to succeed wins. The state machine handles upgrade (LRP → ICE) and fallback transparently.</p>`,17)])])}const g=n(t,[["render",l]]);export{u as __pageData,g as default};
